import csv,collections as c,itertools as it,math
r=list(csv.DictReader(open('data/events.csv')))
for a in r:a.update(day=a['ts'][:10],month=a['ts'][:7],week=a['ts'][:10])
print(len(r), min(a['ts'] for a in r),max(a['ts'] for a in r))
for k in r[0]:
 print(k,len(set(a[k] for a in r)),sum(not a[k] for a in r))
print(c.Counter(a['status'] for a in r))
def groups(keys, rows=r):
 d=c.defaultdict(list)
 for a in rows:d[tuple(a[k] for k in keys)].append(a)
 return d
def stat(v):return (sum(a['status']=='error' for a in v),len(v))
keys='plan region endpoint client_version'.split()
for ks in [(k,) for k in keys+['month','day']]:
 print(ks,[(k,stat(v)) for k,v in sorted(groups(ks).items())])
p=stat(r)[0]/len(r)
for n in range(2,5):
 out=[]
 for ks in it.combinations(keys,n):
  for k,v in groups(ks).items():
   e,t=stat(v)
   z=(e-t*p)/(t*p*(1-p))**.5
   if t>=10:out.append((round(z,2),ks,k,e,t))
 print(sorted(out,reverse=True)[:18])
print('accounts', sorted([(stat(v),k) for k,v in groups(['account_id']).items()],reverse=True)[:20])
